def _shuffled(rng, values):
    values = list(values)
    rng.shuffle(values)
    return values


def build_datasets():
    """All datasets from one fixed seed; sizes stay small on purpose."""
    rng = random.Random(SEED)
    n = 120
    ids = rng.sample(range(1, 400), n)
    flags = _shuffled(rng, [True] * 50 + [False] * 40 + [None] * 30)
    scores = _shuffled(
        rng,
        [0.0] * 12
        + [-0.0] * 12
        + [1.5] * 20
        + [-2.25] * 15
        + [3.0] * 10
        + [0.5] * 15
        + [2.5] * 16
        + [None] * 20,
    )
    names = _shuffled(
        rng,
        ["alpha"] * 20
        + ["beta"] * 15
        + ["数据"] * 15
        + ["héllo"] * 10
        + ["🚀launch"] * 8
        + [""] * 7
        + ["O'Brien"] * 5
        + ["gamma δ"] * 10
        + [None] * 30,
    )
    bigs = _shuffled(
        rng,
        [INT64_MAX - 1] * 15
        + [INT64_MAX - 7] * 15
        + [INT64_MIN + 1] * 15
        + [INT64_MIN + 10] * 15
        + [0] * 20
        + [-1] * 20
        + [None] * 20,
