    main_schema = Schema(
        [
            ColumnSchema("id", "int64"),
            ColumnSchema("flag", "bool", nullable=True),
            ColumnSchema("score", "float64", nullable=True),
            ColumnSchema("name", "utf8", nullable=True),
            ColumnSchema("big", "int64", nullable=True),
