            "fk": _shuffled(rng, [0.0, 1.5, -0.0, 2.5, None, 9.5, 1.5, 0.0]),
            "flag": _shuffled(rng, [True, False, None, True, False, None, True, False]),
        },
    )
    return {"main": main, "empty": empty, "l": left, "r": right, "t": third}


